// Define the fleet of transformers to monitor each cycle.
// Replace this with a database/Google Sheet lookup if your fleet changes often.
const fleet = [
  { transformerId: 'TX-1042', substation: 'Substation-North-7', ratedCapacityKw: 2500 },
  { transformerId: 'TX-1043', substation: 'Substation-North-7', ratedCapacityKw: 2500 },
  { transformerId: 'TX-2011', substation: 'Substation-East-3', ratedCapacityKw: 4000 }
];

return fleet.map(t => ({ json: t }));

const item = $input.item.json;

// --- Load data ---
const currentLoadKw = parseFloat(item.currentLoadKw ?? item.current_load_kw ?? item.load_kw) || 0;
const ratedCapacityKw = parseFloat(item.ratedCapacityKw ?? item.rated_capacity_kw) || 1;
const loadPercentage = Math.round((currentLoadKw / ratedCapacityKw) * 1000) / 10;

// --- Temperature data ---
const oilTempC = parseFloat(item.oilTempC ?? item.oil_temp_c) || 0;
const windingTempC = parseFloat(item.windingTempC ?? item.winding_temp_c) || 0;
const ambientTempC = parseFloat(item.ambientTempC ?? item.ambient_temp_c) || 0;

// --- Historical data ---
const historicalAvgLoadPct = parseFloat(item.historicalAvgLoadPercentage ?? item.historical_avg_load_pct) || loadPercentage;
const pastOverloadIncidents = parseInt(item.pastOverloadIncidents ?? item.past_overload_incidents, 10) || 0;
const last30DayPeakLoadPct = parseFloat(item.last30DayPeakLoadPercentage ?? item.last_30_day_peak_load_pct) || loadPercentage;
const loadTrendPct = Math.round((loadPercentage - historicalAvgLoadPct) * 10) / 10;

// Rough conversion of the 30-day trend into a per-hour drift (used for the ETA projection below).
const loadTrendPctPerHour = Math.round((loadTrendPct / (30 * 24)) * 10000) / 10000;

// Flags whether this reading is backed by real sensor + history data, or fell back to defaults.
const dataConfidence = (item.oilTempC !== undefined && item.historicalAvgLoadPercentage !== undefined) ? 'high' : 'low';

// --- Load risk (0-40) ---
let loadRiskScore;
if (loadPercentage >= 100) loadRiskScore = 40;
else if (loadPercentage >= 90) loadRiskScore = 32;
else if (loadPercentage >= 80) loadRiskScore = 20;
else if (loadPercentage >= 70) loadRiskScore = 10;
else loadRiskScore = 2;

// --- Temperature risk (0-35), IEC 60076-style thresholds ---
let tempRiskScore;
if (oilTempC >= 105 || windingTempC >= 140) tempRiskScore = 35;
else if (oilTempC >= 95 || windingTempC >= 120) tempRiskScore = 28;
else if (oilTempC >= 85 || windingTempC >= 105) tempRiskScore = 18;
else if (oilTempC >= 75 || windingTempC >= 95) tempRiskScore = 8;
else tempRiskScore = 1;

// --- Historical / trend risk (0-25) ---
let historyRiskScore = 0;
historyRiskScore += Math.min(pastOverloadIncidents * 4, 12);
if (loadTrendPct >= 10) historyRiskScore += 10;
else if (loadTrendPct >= 5) historyRiskScore += 6;
else if (loadTrendPct >= 0) historyRiskScore += 2;
if (last30DayPeakLoadPct >= 100) historyRiskScore += 3;
historyRiskScore = Math.min(historyRiskScore, 25);

// --- Overall risk score (0-100) ---
const overallRiskScore = Math.min(loadRiskScore + tempRiskScore + historyRiskScore, 100);

let riskLevel = 'Low';
if (overallRiskScore >= 75) riskLevel = 'Critical';
else if (overallRiskScore >= 55) riskLevel = 'High';
else if (overallRiskScore >= 35) riskLevel = 'Medium';

// --- Rough time-to-overload projection ---
let estimatedHoursToOverload = null;
if (loadTrendPct > 0 && loadPercentage < 100) {
  const remainingPct = 100 - loadPercentage;
  estimatedHoursToOverload = Math.round((remainingPct / loadTrendPct) * 24 * 10) / 10;
}

const recommendedAction = riskLevel === 'Critical'
  ? 'Immediate load shedding or transformer swap required.'
  : riskLevel === 'High'
  ? 'Schedule inspection within 24 hours and prepare a load reduction plan.'
  : riskLevel === 'Medium'
  ? 'Monitor closely and review load balancing over the coming week.'
  : 'No action needed. Continue routine monitoring.';

return {
  json: {
    ...item,
    checkedAt: new Date().toISOString(),
    loadPercentage, oilTempC, windingTempC, ambientTempC,
    historicalAvgLoadPct, pastOverloadIncidents, last30DayPeakLoadPct,
    loadTrendPct, loadTrendPctPerHour, dataConfidence,
    loadRiskScore, tempRiskScore, historyRiskScore, overallRiskScore,
    riskLevel, estimatedHoursToOverload, recommendedAction
  }
};

const data = $input.item.json;
const staticData = $getWorkflowStaticData('global');
if (!staticData.lastAlertTimestamps) staticData.lastAlertTimestamps = {};

const cooldownHours = 4; // minimum gap between repeat alerts for the same transformer
const now = Date.now();
const lastAlert = staticData.lastAlertTimestamps[data.transformerId];
const cooldownMs = cooldownHours * 60 * 60 * 1000;

const cooldownActive = !!(lastAlert && (now - lastAlert) < cooldownMs);

if (!cooldownActive) {
  // Record the alert time immediately so a second cycle a few minutes from now
  // (before this email even sends) doesn't also slip through the cooldown check.
  staticData.lastAlertTimestamps[data.transformerId] = now;
}

return {
  json: {
    ...data,
    cooldownActive,
    cooldownHours,
    lastAlertTimestamp: lastAlert ? new Date(lastAlert).toISOString() : null
  }
};
